insert into sb_theses (code,author,status,hypothesis,invalidation_conditions,created_at,updated_at) values
('005930','bium','valid','HBM 구조적 수요 + 범용 D램 가격 반등으로 2026 하반기 실적 컨센서스 상향. 3C 베이스(A 380,000→189,200, B 288,000 회복) 완성 후 C 박스 고점 돌파 시 2단계 재개.','[{"text":"288,000 돌파 실패 후 C 박스 하단(250,000) 종가 이탈","violated":false,"note":null},{"text":"HBM4 주요 고객 인증 지연 공식 발표","violated":false,"note":null},{"text":"분기 영업이익 컨센서스 10% 이상 하회","violated":false,"note":null},{"text":"필라델피아 반도체지수 대비 상대강도 3개월 연속 하위","violated":false,"note":null}]'::jsonb,'2026-09-15T22:30:00+09:00','2026-09-15T22:30:00+09:00'),
('999902','brain','valid','[가짜] 신약 3상 결과 발표 전 기관 매집. 2분기 연속 컨센서스 상회.','[]'::jsonb,'2026-10-02T09:30:00+09:00','2026-10-02T09:30:00+09:00'),
('999903','bium','valid','[가짜] LNG선 수주 잔고 3년치 + 신조선가 상승. 4~7주 플랫 베이스 고점 돌파 대기.','[{"text":"신조선가 지수 2개월 연속 하락","violated":false,"note":null},{"text":"베이스 하단(-12%) 종가 이탈","violated":false,"note":null}]'::jsonb,'2026-09-29T20:00:00+09:00','2026-09-29T20:00:00+09:00'),
('999904','bium','suspect','[가짜] 중동 리스크로 유가 90달러 이상 유지 시 정제 마진 확대.','[{"text":"WTI 70달러 하회","violated":true,"note":"9/24 종가 68.4달러"},{"text":"정제 마진 5달러 이하","violated":false,"note":null}]'::jsonb,'2026-09-12T20:00:00+09:00','2026-09-24T07:10:00+09:00');
